/* eslint-disable @typescript-eslint/member-ordering */
import { Component, OnDestroy, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { ModalController } from '@ionic/angular';
import { Router } from '@angular/router';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { GResponse } from 'src/app/core/common/GResponse';
import { GAccount } from 'src/app/core/common/GAccount';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';

import { DynoService } from './dyno.service';
import {
  buildRpmSweep,
  CamshaftCalculated,
  CamshaftPreset,
  CylinderHeadAirflowData,
  CylinderHeadOption,
  CompressionCalculated,
  DynoConfig,
  DynoResultRow,
  ShortBlockCalculated,
} from './dyno.model';
import { calcCamshaft, calcCombustionSpaceCc, calcShortBlock } from './dyno-calc.util';
import { CylinderHeadAirflowDialogComponent } from './cylinder-head-airflow-dialog.component';
import { buildLineChartSvg, ChartSeries } from './dyno-chart.util';

interface SavedDynoProfile {
  id: number;
  name: string;
  config: DynoConfig;
}

@Component({
  selector: 'app-dyno',
  templateUrl: './dyno.component.html',
  styleUrls: ['./dyno.component.scss'],
})
export class DynoComponent implements OnInit, OnDestroy {

  private readonly destroy$ = new Subject<void>();

  isShow = false;
  loading = true;

  form: FormGroup;

  // Option lists shown in the UI selects -----------------------------------
  cylinderHeadOptions: CylinderHeadOption[] = [];
  camshaftPresets: CamshaftPreset[] = [];
  manifoldTypeOptions: string[] = [
    'Single-Plane Manifold',
    'Dual-Plane Manifold',
    'Stock Manifold',
    'Individual Runner (EFI)',
  ];
  exhaustSystemOptions: string[] = [
    'Stock Manifolds And Mufflers',
    'Shorty Headers/Stock Mufflers',
    'Long-Tube Headers/Low-Restriction Mufflers',
    'Long-Tube Headers/Open Exhaust',
  ];
  fuelOptions: string[] = ['Gasoline', 'Racing Gasoline', 'Methanol', 'E85'];
  lifterOptions: string[] = ['Hydraulic Flat Tappet', 'Solid Flat Tappet', 'Hydraulic Roller', 'Solid Roller'];
  camSpecBasisOptions: string[] = ['Seat-To-Seat', 'Advertised', '.050" Tappet Lift'];

  // Live-calculated (read-only) fields --------------------------------------
  shortBlockCalc: ShortBlockCalculated = { cylVolumeCc: 0, totalVolumeCc: 0 };
  compressionCalc: CompressionCalculated = { combustionSpaceCc: 0 };
  camshaftCalc: CamshaftCalculated | null = null;

  // Output ------------------------------------------------------------------
  results: DynoResultRow[] = [];
  baseline: DynoResultRow[] = [];
  baselineName = '';
  modelIssues: string[] = [];
  resultView: 'graph' | 'table' = 'graph';
  workspaceView: 'inputs' | 'results' = 'results';
  chartMetric: 'output' | 'pressure' | 've' | 'map' = 'output';
  chartSvg: SafeHtml | null = null;
  savedProfiles: SavedDynoProfile[] = [];
  selectedProfileId: number | null = null;
  readonly rpmSweep = buildRpmSweep();

  get peakPower(): DynoResultRow | null {
    return this.results.length ? this.results.reduce((a, b) => b.powerFlyHp > a.powerFlyHp ? b : a) : null;
  }

  get peakTorque(): DynoResultRow | null {
    return this.results.length ? this.results.reduce((a, b) => b.torqueFlyLbFt > a.torqueFlyLbFt ? b : a) : null;
  }

  get peakPowerDelta(): number {
    if (!this.baseline.length || !this.peakPower) { return 0; }
    const basePeak = Math.max(...this.baseline.map(r => r.powerFlyHp));
    return Math.round((this.peakPower.powerFlyHp - basePeak) * 10) / 10;
  }

  constructor(
    private readonly fb: FormBuilder,
    private readonly modalCtrl: ModalController,
    private readonly dynoService: DynoService,
    private sanitizer: DomSanitizer,
    private readonly sliderService: SliderService,
    private readonly courseService: CourseService,
    private readonly router: Router,
  ) {
    this.isShow = false;
  }

  ngOnInit(): void {
    this.buildForm();
    this.watchFormChanges();
    this.readProfiles();
    this.checkAccess();
  }

  private checkAccess(): void {
    if (GAccount.IsAdminActive()) {
      this.grantAccess();
      return;
    }
    this.sliderService.GetTunerPlusById(38)
      .pipe(takeUntil(this.destroy$))
      .subscribe(res => {
        if (res?.status !== GResponse.SuccessStatus || !res.data?.isActive) {
          this.denyAccess();
          return;
        }
        if (res.data.isFree) {
          this.grantAccess();
          return;
        }
        this.courseService.GetUserCoursesId()
          .pipe(takeUntil(this.destroy$))
          .subscribe(courses => {
            const permittedCourses = res.data.courseIds || [];
            const ownedCourses = courses?.data || [];
            if (courses?.status !== GResponse.SuccessStatus ||
                !permittedCourses.some(id => ownedCourses.some(ownedId => Number(ownedId) === Number(id)))) {
              this.denyAccess();
              return;
            }
            this.courseService.GetUserTunerPlusAccess()
              .pipe(takeUntil(this.destroy$))
              .subscribe(access => {
                if (access?.status === GResponse.SuccessStatus) {
                  this.grantAccess();
                } else {
                  this.denyAccess();
                }
              }, () => this.denyAccess());
          }, () => this.denyAccess());
      }, () => this.denyAccess());
  }

  private grantAccess(): void {
    this.loadOptions();
    this.isShow = true;
  }

  private denyAccess(): void {
    this.loading = false;
    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  // ---------------------------------------------------------------------
  // Setup
  // ---------------------------------------------------------------------

  private buildForm(): void {
    this.form = this.fb.group({
      shortBlock: this.fb.group({
        block: ['نمونه ۱.۶ لیتری چهار سیلندر', Validators.required],
        bore: [78.5, [Validators.required, Validators.min(1)]],
        stroke: [82.0, [Validators.required, Validators.min(1)]],
        cylinders: [4, [Validators.required, Validators.min(1)]],
      }),
      cylinderHeads: this.fb.group({
        headOptionId: ['4v-stock', Validators.required],
        airflowFile: [null],
        intakeValves: [2, [Validators.required, Validators.min(1)]],
        exhaustValves: [2, [Validators.required, Validators.min(1)]],
        intakeValveDiaMm: [31.30, [Validators.required, Validators.min(0)]],
        exhaustValveDiaMm: [25.50, [Validators.required, Validators.min(0)]],
        customAirflow: [null],
      }),
      compression: this.fb.group({
        compressionRatio: [10.5, [Validators.required, Validators.min(1)]],
      }),
      induction: this.fb.group({
        inductionFlowCfm: [500.0, [Validators.required, Validators.min(0)]],
        inductionFlowPressureDropInHg: [1.50, [Validators.required, Validators.min(0)]],
        fuel: ['Gasoline', Validators.required],
        manifoldType: ['Single-Plane Manifold', Validators.required],
        n2oLbsMin: [0.0, [Validators.min(0)]],
      }),
      forcedInduction: this.fb.group({
        enabled: [false],
        blowerType: ['Turbo-Rajay 300B'],
        flowCfm: [250.0],
        pressureRatio: [3.70],
        intercoolerEfficiencyPct: [85.0],
        boostLimitPsi: [15.0],
        speedRpm: [null],
        beltGearRatio: [null],
        internalGearRatio: [null],
        efficiencyPct: [74.0],
        surgeFlowCfm: [80.0],
      }),
      exhaust: this.fb.group({
        exhaustSystem: ['Stock Manifolds And Mufflers', Validators.required],
      }),
      camshaft: this.fb.group({
        camPresetId: ['stock-street-economy', Validators.required],
        camFile: [null],
        lifterType: ['Hydraulic Flat Tappet', Validators.required],
        camSpecsBasis: ['Seat-To-Seat', Validators.required],
        intLiftAtValveMm: [8.00, [Validators.required, Validators.min(0)]],
        exhLiftAtValveMm: [7.65, [Validators.required, Validators.min(0)]],
        timingAdvRetDeg: [0.0],
        ivoBTDC: [13.5, Validators.required],
        ivcABDC: [49.5, Validators.required],
        evoBBDC: [40.5, Validators.required],
        evcATDC: [16.5, Validators.required],
      }),
    });
  }

  private loadOptions(): void {
    this.cylinderHeadOptions = this.dynoService.getCylinderHeadOptions();
    this.camshaftPresets = this.dynoService.getCamshaftPresets();
    this.recalculateAll();
    this.loading = false;
  }

  private watchFormChanges(): void {
    this.form.valueChanges
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => this.recalculateAll());
  }

  // ---------------------------------------------------------------------
  // Live-calculated read-only fields
  // ---------------------------------------------------------------------

  private recalculateAll(): void {
    const config = this.form.getRawValue() as DynoConfig;

    this.shortBlockCalc = calcShortBlock(config.shortBlock);
    this.compressionCalc = {
      combustionSpaceCc: calcCombustionSpaceCc(
        this.shortBlockCalc.cylVolumeCc,
        config.compression.compressionRatio,
      ),
    };
    this.camshaftCalc = calcCamshaft(config.camshaft);

    this.modelIssues = this.dynoService.validate(config);
    this.results = this.form.valid && !this.modelIssues.length
      ? this.dynoService.calculate(config) : [];
    this.updateChart();
  }

  private updateChart(): void {
    if (!this.results.length) {
      this.chartSvg = null;
      return;
    }
    let series: ChartSeries[];
    let baseValues: number[];
    if (this.chartMetric === 'pressure') {
      series = [
        { label: 'IMEP (psi)', color: '#d62828', values: this.results.map(r => r.imepPsi) },
        { label: 'BMEP (psi)', color: '#d8912d', values: this.results.map(r => r.bmepPsi) },
        { label: 'FMEP (psi)', color: '#699a8b', values: this.results.map(r => r.fmepPsi) },
        { label: 'PMEP (psi)', color: '#9674aa', values: this.results.map(r => r.pmepPsi) },
      ];
      baseValues = this.baseline.map(r => r.bmepPsi);
    } else if (this.chartMetric === 've') {
      series = [{ label: 'VE (%)', color: '#d62828', values: this.results.map(r => r.volEffPct) }];
      baseValues = this.baseline.map(r => r.volEffPct);
    } else if (this.chartMetric === 'map') {
      series = [{ label: 'MAP absolute (inHg)', color: '#d62828', values: this.results.map(r => r.intManPressureInHg) }];
      baseValues = this.baseline.map(r => r.intManPressureInHg);
    } else {
      series = [
        { label: 'Power (hp)', color: '#d62828', values: this.results.map(r => r.powerFlyHp) },
        { label: 'Torque (lb-ft)', color: '#d8912d', values: this.results.map(r => r.torqueFlyLbFt) },
      ];
      baseValues = this.baseline.map(r => r.powerFlyHp);
    }
    if (this.baseline.length === this.results.length) {
      series.push({
        label: 'Baseline', color: '#666b76', values: baseValues,
      });
    }
    const svg = buildLineChartSvg(this.results.map(r => r.rpm), series, {
      width: 800, height: 390, xAxisLabel: 'RPM',
    });
    this.chartSvg = this.sanitizer.bypassSecurityTrustHtml(svg);
  }

  setChartMetric(value: string): void {
    if (value === 'output' || value === 'pressure' || value === 've' || value === 'map') {
      this.chartMetric = value;
      this.updateChart();
    }
  }

  setWorkspaceView(value: string): void {
    if (value === 'inputs' || value === 'results') { this.workspaceView = value; }
  }

  saveBaseline(): void {
    if (!this.results.length) { return; }
    this.baseline = this.results.map(r => ({ ...r }));
    this.baselineName = this.form.get('shortBlock.block').value || 'Baseline';
    this.updateChart();
  }

  clearBaseline(): void {
    this.baseline = [];
    this.baselineName = '';
    this.updateChart();
  }

  baselineAtRpm(rpm: number): DynoResultRow | undefined {
    return this.baseline.find(r => r.rpm === rpm);
  }

  exportCsv(): void {
    if (!this.results.length) { return; }
    const columns: (keyof DynoResultRow)[] = [
      'rpm', 'powerFlyHp', 'torqueFlyLbFt', 'intManPressureInHg',
      'volEffPct', 'imepPsi', 'fmepPsi', 'pmepPsi', 'bmepPsi',
    ];
    const lines = [columns.join(','), ...this.results.map(row => columns.map(key => row[key]).join(','))];
    const url = URL.createObjectURL(new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = 'avalamooz-dyno.csv';
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  private readProfiles(): void {
    try {
      const stored = JSON.parse(localStorage.getItem('st-dyno-profiles-v1') || '[]');
      this.savedProfiles = Array.isArray(stored) ? stored.filter(p => p && p.config && p.name).slice(0, 12) : [];
    } catch {
      this.savedProfiles = [];
    }
  }

  private writeProfiles(): void {
    try { localStorage.setItem('st-dyno-profiles-v1', JSON.stringify(this.savedProfiles)); } catch { /* private browsing */ }
  }

  saveProfile(): void {
    if (!this.results.length) { return; }
    const name = String(this.form.get('shortBlock.block').value || 'Engine').trim().slice(0, 60);
    const profile = { id: Date.now(), name, config: this.form.getRawValue() as DynoConfig };
    this.savedProfiles = [profile, ...this.savedProfiles].slice(0, 12);
    this.selectedProfileId = profile.id;
    this.writeProfiles();
  }

  loadProfile(): void {
    const profile = this.savedProfiles.find(p => p.id === Number(this.selectedProfileId));
    if (profile) { this.form.patchValue(profile.config); }
  }

  deleteProfile(): void {
    this.savedProfiles = this.savedProfiles.filter(p => p.id !== Number(this.selectedProfileId));
    this.selectedProfileId = null;
    this.writeProfiles();
  }

  // ---------------------------------------------------------------------
  // Cylinder head selection / custom airflow dialog
  // ---------------------------------------------------------------------

  get isCustomCylinderHead(): boolean {
    const opt = this.cylinderHeadOptions.find(
      o => o.id === this.form.get('cylinderHeads.headOptionId').value,
    );
    return !!opt?.isCustom;
  }

  onCylinderHeadChanged(): void {
    if (this.isCustomCylinderHead) {
      this.openCylinderHeadAirflowDialog();
    } else {
      const opt = this.cylinderHeadOptions.find(
        o => o.id === this.form.get('cylinderHeads.headOptionId').value,
      );
      this.form.get('cylinderHeads.airflowFile').setValue(opt?.flwFileId ?? null);
      if (opt?.id.startsWith('2v') || opt?.id.startsWith('4v')) {
        const count = opt.id.startsWith('2v') ? 1 : 2;
        this.form.get('cylinderHeads').patchValue({ intakeValves: count, exhaustValves: count });
      }
    }
  }

  async openCylinderHeadAirflowDialog(existing?: CylinderHeadAirflowData): Promise<void> {
    const modal = await this.modalCtrl.create({
      component: CylinderHeadAirflowDialogComponent,
      componentProps: { data: existing ?? null },
    });

    modal.onDidDismiss().then(({ data }: { data?: CylinderHeadAirflowData }) => {
      if (data) {
        this.form.get('cylinderHeads.customAirflow').setValue(data);
        this.form.get('cylinderHeads.airflowFile').setValue(data.description || 'Custom');
      }
    });

    await modal.present();
  }

  // ---------------------------------------------------------------------
  // Camshaft preset selection
  // ---------------------------------------------------------------------

  get isCustomCamshaft(): boolean {
    const preset = this.camshaftPresets.find(
      p => p.id === this.form.get('camshaft.camPresetId').value,
    );
    return !!preset?.isCustom;
  }

  onCamshaftPresetChanged(): void {
    const preset = this.camshaftPresets.find(
      p => p.id === this.form.get('camshaft.camPresetId').value,
    );
    this.form.get('camshaft.camFile').setValue(preset?.camFileId ?? null);
    const events = this.dynoService.getCamEvents(preset?.id);
    if (events) { this.form.get('camshaft').patchValue(events); }
  }
}
