// dyno.model.ts
// Data model for the Dyno2000-style engine dyno simulator (Tuner Plus)
// Mirrors the "Engine" input tab (left panel) and the "Table" output tab (right panel)

// =========================================================
// SHORT BLOCK
// =========================================================
export interface ShortBlockInput {
  block: string;           // e.g. 'Buick 112 4-OHC'  (engine family / preset id)
  bore: number;             // mm
  stroke: number;           // mm
  cylinders: number;        // e.g. 4, 6, 8
}

export interface ShortBlockCalculated {
  cylVolumeCc: number;      // per-cylinder swept volume (cc)
  totalVolumeCc: number;    // total displacement (cc)
}

// =========================================================
// CYLINDER HEADS
// =========================================================
export interface CylinderHeadOption {
  id: string;
  label: string;            // e.g. '4-Valve Head/Stock Ports And Valves'
  isCustom?: boolean;       // true for the "Custom Airflow Data..." entry
  flwFileId?: string | null; // reference to a parsed .flw file (see flw-parser.util.ts)
}

export interface CylinderHeadsInput {
  headOptionId: string;         // selected CylinderHeadOption.id
  airflowFile: string | null;   // resolved .flw file name/id, '***' if not applicable
  intakeValves: number;         // valves per cylinder, intake
  exhaustValves: number;        // valves per cylinder, exhaust
  intakeValveDiaMm: number;     // mm
  exhaustValveDiaMm: number;    // mm
  customAirflow?: CylinderHeadAirflowData | null; // set when headOptionId is custom
}

// =========================================================
// COMPRESSION
// =========================================================
export interface CompressionInput {
  compressionRatio: number; // e.g. 10.5
}

export interface CompressionCalculated {
  combustionSpaceCc: number;
}

// =========================================================
// INDUCTION (naturally aspirated path)
// =========================================================
export type FuelType = 'Gasoline' | 'Racing Gasoline' | 'Methanol' | 'E85';

export interface InductionInput {
  inductionFlowCfm: number;       // e.g. 500.0
  inductionFlowPressureDropInHg: number; // e.g. 1.50 inHg (test pressure drop for the flow rating)
  fuel: FuelType;
  manifoldType: string;           // e.g. 'Single-Plane Manifold'
  n2oLbsMin: number;              // 0 when not used
}

// =========================================================
// FORCED INDUCTION (simplified compressor envelope, no transient spool model)
// =========================================================
export interface ForcedInductionInput {
  enabled: boolean;
  blowerType: string;      // e.g. 'Turbo-Rajay 300B'
  flowCfm: number;
  pressureRatio: number;
  intercoolerEfficiencyPct: number;
  boostLimitPsi: number;
  speedRpm: number | null;
  beltGearRatio: number | null;
  internalGearRatio: number | null;
  efficiencyPct: number;
  surgeFlowCfm: number;
}

// =========================================================
// EXHAUST
// =========================================================
export interface ExhaustInput {
  exhaustSystem: string; // e.g. 'Stock Manifolds And Mufflers'
}

// =========================================================
// CAMSHAFT
// =========================================================
export type LifterType = 'Hydraulic Flat Tappet' | 'Solid Flat Tappet' | 'Hydraulic Roller' | 'Solid Roller';
export type CamSpecBasis = 'Seat-To-Seat' | 'Advertised' | '.050" Tappet Lift';

export interface CamshaftPreset {
  id: string;
  label: string;       // e.g. 'Stock Street/Economy'
  isCustom?: boolean;   // true for the "Custom..." entry, enables manual IVO/IVC/EVO/EVC
  camFileId?: string | null; // reference to a parsed .cam file (see cam-parser.util.ts)
}

export interface CamshaftInput {
  camPresetId: string;
  camFile: string | null;
  lifterType: LifterType;
  camSpecsBasis: CamSpecBasis;
  intLiftAtValveMm: number;
  exhLiftAtValveMm: number;
  timingAdvRetDeg: number; // + = advance, - = retard

  // Nominal (as-designed, before Adv/Ret shift) valve events, degrees
  ivoBTDC: number;  // Intake Valve Opens, degrees Before TDC
  ivcABDC: number;  // Intake Valve Closes, degrees After BDC
  evoBBDC: number;  // Exhaust Valve Opens, degrees Before BDC
  evcATDC: number;  // Exhaust Valve Closes, degrees After TDC
}

export interface CamshaftCalculated {
  lobeCenterDeg: number;
  valveOverlapDeg: number;  // IVO + EVC
  intDurationDeg: number;   // IVO + 180 + IVC
  exhDurationDeg: number;   // EVO + 180 + EVC

  // Nominal event angles, restated in ATDC-based intake / BTDC-based exhaust form
  icaATDC: number;          // Intake Centerline Angle, ATDC
  ecaBTDC: number;          // Exhaust Centerline Angle, BTDC

  // Shifted (post Adv/Ret) valve events actually used to index the VE curve
  ivoShifted: number;
  ivcShifted: number;
  evoShifted: number;
  evcShifted: number;
}

// =========================================================
// CYLINDER HEAD CUSTOM AIRFLOW DATA (matches the "Cylinder Head Airflow Data" dialog)
// =========================================================
export interface CylinderHeadAirflowPoint {
  liftMm: number | null;
  flowCfm: number | null;
}

export interface CylinderHeadAirflowSide {
  testDiameterMm: number;
  pressureDropCmH2O: number;
  points: CylinderHeadAirflowPoint[]; // length == dataPoints
}

export interface CylinderHeadAirflowData {
  description: string;
  dataPoints: number; // e.g. 8, up to 10 rows in the dialog
  intake: CylinderHeadAirflowSide;
  exhaust: CylinderHeadAirflowSide;
}

// =========================================================
// FULL CONFIG (bound to the reactive form)
// =========================================================
export interface DynoConfig {
  shortBlock: ShortBlockInput;
  cylinderHeads: CylinderHeadsInput;
  compression: CompressionInput;
  induction: InductionInput;
  forcedInduction: ForcedInductionInput;
  exhaust: ExhaustInput;
  camshaft: CamshaftInput;
}

// =========================================================
// OUTPUT TABLE ("CALCULATED POWER AND ENGINE PRESSURES")
// =========================================================
export interface DynoResultRow {
  rpm: number;
  powerFlyHp: number;      // Power (Fly)
  torqueFlyLbFt: number;   // Torque (Fly)
  intManPressureInHg: number; // Int Man Pressure (absolute)
  volEffPct: number;       // Vol Eff %
  imepPsi: number;
  fmepPsi: number;
  pmepPsi: number;        // intake and exhaust pumping loss
  bmepPsi: number;
}

export const DYNO_RPM_START = 2000;
export const DYNO_RPM_END = 11000;
export const DYNO_RPM_STEP = 500;

export function buildRpmSweep(
  start: number = DYNO_RPM_START,
  end: number = DYNO_RPM_END,
  step: number = DYNO_RPM_STEP
): number[] {
  const rpms: number[] = [];
  for (let rpm = start; rpm <= end; rpm += step) {
    rpms.push(rpm);
  }
  return rpms;
}
